// Build-time Bible maps and timeline data (generated by scripts/generate-bible-maps.mjs).
import placesJson from "./places.json";
import timelineJson from "./timeline.json";

/** Easton paragraph segment: plain text, or [text, fromCode, toCode?] scripture link. */
export type EastonSeg = string | [string, number] | [string, number, number];
export type Place = {
  slug: string;
  name: string;
  label: string;
  types: string[];
  lon: number | null;
  lat: number | null;
  /** OpenBible.info confidence for the best identification, 0–1000. */
  score: number;
  alts: { name: string; lon: number; lat: number; score: number; kind?: string }[];
  bestName: string | null;
  verses: number[];
  hint: string | null;
  easton?: EastonSeg[][];
  events?: string[];
};
export type TimelineEvent = {
  id: string;
  title: string;
  /** Astronomical year (0 = 1 BC), traditional chronology. */
  year: number;
  years: number;
  kind: "event" | "period" | "life";
  era: number;
  verses: ([number] | [number, number])[];
  people: string[];
  places: string[];
  notes?: string;
};
export type Era = { id: string; title: string; start: number };

export const places = placesJson as Place[];
export const timeline = timelineJson as { eras: Era[]; events: TimelineEvent[] };
export const placeBySlug = new Map(places.map(p => [p.slug, p]));
export const eventById = new Map(timeline.events.map(e => [e.id, e]));
